<script setup lang="ts">
import {ref,computed,onMounted} from 'vue';
import {go} from '../router';
import {jointPlans,jointRuns} from '../stores/joint';
import {datasets} from '../stores/datasets';
import {specs} from '../stores/specs';
import {canWrite} from '../stores/auth';
import {useTask} from '../hooks/useTask';
import {fixed} from '../utils/format';
import PageHeading from '../components/common/PageHeading.vue';
import Notice from '../components/common/Notice.vue';
const name=ref(''),dataset=ref('demo-dataset'),limit=ref(30),note=ref('');
const rows=ref<any[]>([{order_id:'CY-2211',name:'涂布文化纸',tonnes:30,spec_id:'demo-spec-coated'},{order_id:'BD-2211',name:'包装纸板',tonnes:18,spec_id:'demo-spec-board'}]);
const inventory=ref<Record<string,number>>({});
const {error,busy,act}=useTask();
const materials=computed<any[]>(()=>datasets.items.value.find(r=>r.id===dataset.value)?.materials||[]);
onMounted(async()=>{await Promise.all([jointPlans.load(),jointRuns.load(),datasets.load(),specs.load()]);if(!datasets.items.value.some(r=>r.id===dataset.value))dataset.value=datasets.items.value[0]?.id||'';const specIds=specs.items.value.map(r=>r.id);for(const r of rows.value)if(!specIds.includes(r.spec_id))r.spec_id=specIds[0]||'';syncInventory()});
function syncInventory(){const next:Record<string,number>={};for(const m of materials.value)next[m.material_id]=inventory.value[m.material_id]??0;inventory.value=next}
function addOrder(){if(rows.value.length<8)rows.value.push({order_id:'',name:'',tonnes:10,spec_id:specs.items.value[0]?.id||''})}
function removeOrder(index:number){rows.value.splice(index,1)}
function validate():string{const ids=rows.value.map(r=>String(r.order_id||'').trim());if(!rows.value.length)return '至少需要一个订单';if(ids.some(id=>!id))return '订单编号不能为空';if(new Set(ids).size!==ids.length)return '订单编号不能重复';for(const r of rows.value){if(!(Number(r.tonnes)>0))return `订单${r.order_id}吨数须为正`;const packs=Number(r.tonnes)/0.5;if(Math.abs(packs-Math.round(packs))>1e-9)return `订单${r.order_id}吨数须为0.5吨整包`;if(!r.spec_id)return `订单${r.order_id}须选择质量窗口`}if(!Object.values(inventory.value).some(v=>Number(v)>0))return '请至少录入一种原浆库存';if(Object.values(inventory.value).some(v=>Number(v)<0))return '库存不能为负';return ''}
function submit(){act(async()=>{const problem=validate();if(problem)throw new Error(problem);await jointPlans.create({name:name.value,dataset_id:dataset.value,orders:rows.value.map(r=>({order_id:String(r.order_id).trim(),name:String(r.name||r.order_id).trim(),tonnes:Number(r.tonnes),spec_id:r.spec_id})),inventory:Object.fromEntries(Object.entries(inventory.value).map(([k,v])=>[k,Number(v)])),time_limit_seconds:Number(limit.value),note:note.value});name.value=''})}
function execute(id:string){act(async()=>{const r=await jointRuns.create({plan_id:id});go('/joint-results?run='+r.id)})}
const latest=computed<Record<string,any>>(()=>{const map:Record<string,any>={};for(const run of jointRuns.items.value)if(!map[run.plan_id])map[run.plan_id]=run;return map});
function outcome(run:any){if(!run)return '';if(run.result?.feasible)return `总成本 ${fixed(run.result.total_cost)} 元 · 下界 ${fixed(run.result.lower_bound)} · 差距 ${fixed((run.result.gap||0)*100,3)}%`;return run.error||run.result?.reason||''}
</script>
<template><PageHeading index="06 / 联合排产" title="同一批原浆，多个纸种同时排。" note="各纸种沿用原浆供给比例与质量界限，原浆用量按0.5吨整包；全部订单共享库存。求全部订单同时满足的最低总成本，30秒内未证最优则给已核验可行解、成本下界与差距。"/><Notice :message="error"/><div class="two-col"><section><article v-for="p in jointPlans.items.value" :key="p.id" class="plan-row"><p class="eyebrow">JOINT SCHEDULING PLAN</p><h2>{{p.name}}</h2><p>{{p.note}}</p><dl><div><dt>订单数</dt><dd>{{p.orders.length}}</dd></div><div><dt>共享原浆</dt><dd>{{Object.keys(p.inventory).length}}</dd></div><div><dt>时限</dt><dd>{{p.time_limit_seconds}}秒</dd></div></dl><p v-if="latest[p.id]"><small>{{outcome(latest[p.id])}}</small></p><div class="actions"><button v-if="canWrite()" :disabled="busy" @click="execute(p.id)">联合求解 {{p.orders.length}} 单 →</button><a v-if="latest[p.id]" :href="'#/joint-results?run='+latest[p.id].id">查看用量与结余 ↗</a></div></article><p v-if="!jointPlans.items.value.length" class="empty">还没有联合排产方案。先在右侧录入订单、质量窗口与各原浆库存。</p></section><form v-if="canWrite()" class="editor-panel" @submit.prevent="submit"><h2>新建联合排产</h2><label>方案名称<input v-model="name" required minlength="2"></label><label>原浆批次<select v-model="dataset" @change="syncInventory()"><option v-for="r in datasets.items.value" :key="r.id" :value="r.id">{{r.name}}</option></select></label><label>计算时限（秒，≤30）<input type="number" v-model.number="limit" min="1" max="30" step="1"></label><h3>订单（最多8个，吨数须为0.5整包）</h3><div v-for="(r,i) in rows" :key="i" class="order-row-mini"><input v-model="r.order_id" placeholder="订单编号" maxlength="60"><input v-model="r.name" placeholder="纸种名称" maxlength="180"><input type="number" v-model.number="r.tonnes" min="0.5" step="0.5" placeholder="吨数"><select v-model="r.spec_id"><option v-for="s in specs.items.value" :key="s.id" :value="s.id">{{s.name}}</option></select><button type="button" class="secondary" :disabled="rows.length<=1" @click="removeOrder(i)">移除</button></div><button type="button" class="secondary" :disabled="rows.length>=8" @click="addOrder">增加订单</button><h3>各原浆库存（吨）</h3><div v-for="m in materials" :key="m.material_id" class="inventory-input"><span>{{m.name}} <small>{{m.material_id}}</small></span><input type="number" v-model.number="inventory[m.material_id]" min="0" step="0.5"></div><label>方案说明<textarea v-model="note" rows="2"></textarea></label><Notice :message="error"/><button :disabled="busy">保存联合排产方案</button></form></div></template>
